//   og_meta_registry()    - per-work metadata rows. Provenance:
//     name/author/year : csl-atlas/data/dictionary_inventory.csv columns
//                        full_name / author_or_compiler / year
//     entries          : csl-atlas/data/headwords.json L_count (count of
//                        L-records in the csl-orig source file)
//     name fallback    : csl-websanlexicon/v02/dictparms.py alldictparms
//                        dictname (nmmb, nybj are absent from the atlas
//                        inventory)
//     scan/tool rows   : the consuming repos' own READMEs (whitroot: Whitney,
//                        Leipzig 1885, 284 page images; kale: M. R. Kale;
//                        westergaard: Westergaard DhatuPatha; inflect: the
//                        lookup tool itself)
// Regenerate the rows when those sources move; keep this provenance comment
// truthful.
//
// og:image is ONE committed Cologne-owned 1200x630 card:
// csl-apidev og/site_card.png (rendered by make_site_card.py). Every surface
// points at that single absolute URL - no per-page images and no
// cross-property lookups (H6478 ruling: Cologne-owned set, nothing at kosha
// or samskrtam.ru). twitter:card=summary_large_image is paired with it
// (canary-verified in H6478: Telegram needs it for the large preview).

function og_meta_site_config() {
 return array(
  'name'  => 'Cologne Digital Sanskrit Dictionaries',
  'url'   => 'https://www.sanskrit-lexicon.uni-koeln.de/',
  'image' => 'https://www.sanskrit-lexicon.uni-koeln.de/scans/awork/apidev/og/site_card.png',
  'owner' => 'University of Cologne',
 );
}

