function og_meta_escape($s) {
 return htmlspecialchars((string)$s, ENT_QUOTES, 'UTF-8');
}

function og_meta_count_dicts() {
 $n = 0;
 foreach (og_meta_registry() as $row) {
  if (isset($row['kind']) && $row['kind'] === 'dict') {
   $n++;
  }
 }
 return $n;
}

function og_meta_request_url() {
 $site = og_meta_site_config();
 if (PHP_SAPI === 'cli' || !isset($_SERVER['REQUEST_URI'])) {
  return $site['url'];
 }
 $scheme = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') ? 'https' : 'http';
 $host = isset($_SERVER['HTTP_HOST']) ? $_SERVER['HTTP_HOST'] : '';
 if ($host === '') {
  return $site['url'];
 }
 return $scheme . '://' . $host . $_SERVER['REQUEST_URI'];
}

function og_meta_description(array $row) {
 $site = og_meta_site_config();
 $name = isset($row['name']) && $row['name'] !== '' ? $row['name'] : $site['name'];
 if (!empty($row['year'])) {
  $name .= ' (' . $row['year'] . ')';
 }
 $parts = array($name);
 if (!empty($row['author'])) {
  $parts[] = $row['author'];
 }
 if (!empty($row['entries'])) {
  $parts[] = number_format((int)$row['entries']) . ' entries';
 }
 if (!empty($row['extent'])) {
  $parts[] = $row['extent'];
 }
 return implode(' · ', $parts) . '. ' . $site['name'] . ' — ' . $site['owner'] . '.';
}

function og_meta_block($title, $description, $url) {
 $site = og_meta_site_config();
 $lines = array(
  '<meta property="og:type" content="website">',
  '<meta property="og:site_name" content="' . og_meta_escape($site['name']) . '">',
  '<meta property="og:title" content="' . og_meta_escape($title) . '">',
  '<meta property="og:description" content="' . og_meta_escape($description) . '">',
  '<meta property="og:url" content="' . og_meta_escape($url) . '">',
  '<meta property="og:image" content="' . og_meta_escape($site['image']) . '">',
  '<meta property="og:image:width" content="1200">',
  '<meta property="og:image:height" content="630">',
  '<meta name="twitter:card" content="summary_large_image">',
  '<meta name="twitter:title" content="' . og_meta_escape($title) . '">',
  '<meta name="twitter:description" content="' . og_meta_escape($description) . '">',
  '<meta name="twitter:image" content="' . og_meta_escape($site['image']) . '">',
 );
 return implode("\n", $lines) . "\n";
}

// og_meta_page(key, label='', override=array()) - one dictionary or scan-work
// surface. $label is a short surface noun ('Scan', 'List display'), never
// prose; $override carries caller-side metadata for pages with no registry row.
function og_meta_page($key, $label = '', array $override = array()) {
 $site = og_meta_site_config();
 $key = strtolower((string)$key);
 $reg = og_meta_registry();
 $row = isset($reg[$key]) ? $reg[$key] : array();
 $row = array_merge($row, $override);
 $name = !empty($row['name']) ? $row['name'] : ($key !== '' ? strtoupper($key) : $site['name']);
 $title = $name . ($label !== '' ? ' ' . $label : '') . ' — ' . $site['name'];
 return og_meta_block($title, og_meta_description($row), og_meta_request_url());
}

// og_meta_site(label='') - site-level surface with no single work behind it
// (listview, simple search, error shells). The dictionary count is data
// (registry rows with kind=dict).
function og_meta_site($label = '') {
 $site = og_meta_site_config();
 $n = og_meta_count_dicts();
 $title = ($label !== '' ? $label . ' — ' : '') . $site['name'];
 $desc = ($label !== '' ? $label . ' across ' : '')
       . $n . ' dictionaries — ' . $site['name'] . '. ' . $site['owner'] . '.';
 return og_meta_block($title, $desc, og_meta_request_url());
}
